import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    opp_rate = opp_c / n

    # Endgame: last rounds, exploit unless opponent is essentially always cooperative.
    remaining = 100 - n
    if remaining <= 1:
        if opp_d == 0 and n >= 10:
            return 'D'
        if opp_rate > 0.95 and n >= 20:
            return 'C'
        return 'D'
    if remaining <= 4:
        if opp_rate > 0.9 and opp_d <= 1:
            return 'C'
        return 'D'
    if remaining <= 9:
        if opp_rate > 0.85:
            return 'C' if rng.random() < 0.35 else 'D'
        return 'D'

    # Identify very cooperative opponent: mostly cooperate but sprinkle cheap exploits early/mid.
    if n >= 12 and opp_d == 0:
        # Try occasional defections to extract 5s but keep enough cooperation to avoid losing them.
        if n >= 20 and rng.random() < 0.10:
            return 'D'
        return 'C'

    if n >= 15 and opp_rate >= 0.9:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Identify very defective opponent: defect hard, rare probe C to test reactivity.
    if n >= 8 and opp_rate <= 0.15:
        if n < 90 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # Compute recent statistics.
    win = min(12, n)
    recent_op = op[-win:]
    recent_me = me[-win:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_my_c = sum(1 for x in recent_me if x == 'C')

    # Opponent run stats.
    run_op_d = 0
    for x in reversed(op):
        if x == 'D':
            run_op_d += 1
        else:
            break
    run_op_c = 0
    for x in reversed(op):
        if x == 'C':
            run_op_c += 1
        else:
            break
    run_my_d = 0
    for x in reversed(me):
        if x == 'D':
            run_my_d += 1
        else:
            break
    run_my_c = 0
    for x in reversed(me):
        if x == 'C':
            run_my_c += 1
        else:
            break

    last_op = op[-1]
    last_me = me[-1]

    # Strong punishment for long opponent defection streak, but don't lock forever.
    if run_op_d >= 4:
        # If we've also been defecting for a while, occasionally try C to break DD.
        if run_my_d >= 4 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if run_op_d == 3:
        return 'D'

    # Opponent defected recently but not long streak.
    if run_op_d >= 1:
        # If opponent has been very cooperative overall, forgive noise-like isolated D.
        if opp_rate >= 0.82 and run_op_d == 1 and n >= 10:
            # Don't forgive too often under exploitation; but pure noise forgiveness is good here.
            if recent_opp_c >= recent_opp_c + 0 and run_op_c >= 0:
                # Forgive with strong probability.
                if rng.random() < 0.75:
                    return 'C'
                return 'D'
        # Moderate opponent: retaliate but avoid endless DD.
        if run_my_d >= 3 and run_op_d <= 2 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # Reward long cooperation with cooperation.
    if run_op_c >= 5:
        # Very long mutual cooperation: occasionally test to detect pure cooperators.
        if n >= 25 and opp_rate >= 0.9 and rng.random() < 0.07:
            return 'D'
        return 'C'

    # If opponent cooperated after we defected, that signals forgiving/cooperative; exploit a little.
    if last_me == 'D' and last_op == 'C':
        if opp_rate >= 0.7 and n < 85:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        return 'C'

    # Mixed opponent: use mildly forgiving TFT with controlled probing.
    if recent_opp_c >= win - 1 and recent_my_c >= win - 1:
        return 'C'

    # If opponent's defection rate is moderate-low, prefer cooperation.
    if opp_rate >= 0.55:
        if rng.random() < 0.06 and n < 85:
            return 'D'
        return 'C'

    # Opponent's defection rate is non-trivial: reciprocate with mild randomness.
    if opp_rate >= 0.3:
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Otherwise defect.
    return 'D'
